import { constants } from 'node:fs';
import { constants as promiseConstants } from 'node:fs/promises';
function main(): void {
  const c: any = promiseConstants;
  console.log('fs/promises constants', typeof c, Object.keys(c).length, Object.getPrototypeOf(c) === null);
  console.log(Object.keys(c).map((k: string): string => k + '=' + c[k]).join(' '));
  const f: any = constants;
  console.log('fs constants', typeof f, Object.keys(f).length, Object.getPrototypeOf(f) === null, f.O_NONBLOCK, f.S_IRWXU, f.UV_DIRENT_BLOCK);
}
